package cn.mop.api;

import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.springframework.mock.env.MockEnvironment;
import java.math.BigDecimal;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;

class MonitoringScrapeObservationTest {
    static final String TENANT="79000000-0000-4000-8000-000000000001";
    static final Instant NOW=Instant.parse("2026-10-22T12:00:00Z");
    static ObjectNode config(String preset,boolean enabled){var c=MonitoringPresetTest.config(preset);var row=MonitoringPresetTest.row(c);row.put("tenant_id",TENANT).put("enabled",enabled).put("interval_seconds",30);return c;}
    static MonitoringPresetRegistry.Target target(String preset,boolean enabled){var c=config(preset,enabled);return MonitoringPresetTest.first(MonitoringPresetTest.registry(c),c);}
    static MonitoringScrapeObservationService.Source source(String endpoint){return new MonitoringScrapeObservationService.Source(TENANT,URI.create(endpoint),60,300,1);}
    static ObjectNode response(MonitoringPresetRegistry.Target t,String state,String sample){
        var root=MonitoringPresetRegistry.JSON.createObjectNode().put("status","success");var rows=root.putObject("data").put("resultType","vector").putArray("result");
        for(String kind:List.of("state","sample_time")){var row=rows.addObject();row.putObject("metric").put("mop_tenant_id",t.tenantId()).put("mop_asset_id",t.assetId()).put("mop_target_id",t.id()).put("mop_preset",t.preset().id()).put("instance",t.downstream()==null?t.endpoint().getRawAuthority():t.downstream()).put("job","synthetic-job").put("mop_read_kind",kind);row.putArray("value").add(BigDecimal.valueOf(NOW.toEpochMilli(),3)).add(kind.equals("state")?state:sample);}
        return root;
    }
    static String seconds(Instant time){return BigDecimal.valueOf(time.toEpochMilli(),3).toPlainString();}
    static byte[] bytes(ObjectNode node){return node.toString().getBytes(StandardCharsets.UTF_8);}
    static Map<String,Object> decode(ObjectNode node,MonitoringPresetRegistry.Target t){return MonitoringScrapeObservationService.decode(bytes(node),t,NOW,NOW,60,300);}
    static void invalid(ObjectNode node,MonitoringPresetRegistry.Target t){assertThrows(MonitoringScrapeObservationService.InvalidResponse.class,()->decode(node,t));}
    static ArrayNode rows(ObjectNode node){return (ArrayNode)node.path("data").path("result");}
    @Test void freshSuccessAndFailureAreScrapeOnly(){var t=target("linux-node",true);assertEquals("SCRAPE_SUCCEEDED",decode(response(t,"1",seconds(NOW.minusSeconds(5))),t).get("observation_status"));assertEquals("SCRAPE_FAILED",decode(response(t,"0",seconds(NOW.minusSeconds(5))),t).get("observation_status"));}
    @Test void actualSampleTimeControlsFreshnessNotQueryTime(){var t=target("linux-node",true);var result=decode(response(t,"1",seconds(NOW.minusSeconds(61))),t);assertEquals("STALE",result.get("observation_status"));assertNull(result.get("scrape_up"));assertEquals(new BigDecimal("61.000"),result.get("sample_age_seconds"));assertEquals("SCRAPE_SUCCEEDED",decode(response(t,"1",seconds(NOW.minusSeconds(60))),t).get("observation_status"));}
    @Test void receiptDelayCountsTowardsFreshness(){var t=target("linux-node",true);var r=MonitoringScrapeObservationService.decode(bytes(response(t,"1",seconds(NOW.minusSeconds(59)))),t,NOW,NOW.plusSeconds(2),60,300);assertEquals("STALE",r.get("observation_status"));}
    @Test void emptyResultIsNotZeroOrSuccess(){var t=target("linux-node",true);var r=response(t,"1",seconds(NOW));rows(r).removeAll();assertEquals("NO_DATA",decode(r,t).get("observation_status"));}
    @Test void ambiguousIncompleteAndMixedJobsNeverChooseFirst(){var t=target("linux-node",true);var r=response(t,"1",seconds(NOW));rows(r).add(rows(r).get(0).deepCopy());invalid(r,t);r=response(t,"1",seconds(NOW));rows(r).remove(1);invalid(r,t);r=response(t,"1",seconds(NOW));((ObjectNode)rows(r).get(1).get("metric")).put("job","other");invalid(r,t);r=response(t,"1",seconds(NOW));rows(r).set(1,rows(r).get(0).deepCopy());invalid(r,t);}
    @Test void identityAndInstanceMustMatchRegisteredTarget(){var t=target("linux-node",true);for(String field:List.of("mop_tenant_id","mop_asset_id","mop_target_id","mop_preset","instance")){var r=response(t,"1",seconds(NOW));for(var row:rows(r))((ObjectNode)row.get("metric")).put(field,"foreign");invalid(r,t);}}
    @Test void numericFutureAndEvaluationTimeAttacksFail(){var t=target("linux-node",true);for(String value:List.of("NaN","Inf","-Inf","1e999999999","1e-999999999","2","1.1"," ","null"))invalid(response(t,value,seconds(NOW)),t);invalid(response(t,"1",seconds(NOW.plusMillis(1))),t);invalid(response(t,"1","-1"),t);var r=response(t,"1",seconds(NOW));((ArrayNode)rows(r).get(0).get("value")).set(0,new LongNode(0));invalid(r,t);}
    @Test void sampleOutsideConfiguredLookbackIsRejected(){var t=target("linux-node",true);invalid(response(t,"1",seconds(NOW.minusSeconds(301))),t);}
    @Test void nonemptyWarningsAndInfosNeverHidePartialData(){var t=target("linux-node",true);for(String key:List.of("warnings","infos")){var r=response(t,"1",seconds(NOW));r.putArray(key).add("private upstream message");invalid(r,t);r=response(t,"1",seconds(NOW));r.putArray(key);assertEquals("SCRAPE_SUCCEEDED",decode(r,t).get("observation_status"));}}
    @Test void malformedUtf8DuplicateKeysTrailingDocumentsAndOversizeFail(){var t=target("linux-node",true);for(byte[] b:List.of(new byte[]{(byte)0xc3,(byte)0x28},"{} {}".getBytes(),"{\"status\":\"success\",\"status\":\"success\"}".getBytes(),new byte[2*1024*1024+1]))assertThrows(MonitoringScrapeObservationService.InvalidResponse.class,()->MonitoringScrapeObservationService.decode(b,t,NOW,NOW,60,300));}
    @Test void allPrometheusPresetBindingsUseCorrectInstance(){for(var p:MonitoringPresetRegistry.presets().values())if(p.engine().equals("prometheus")){var t=target(p.id(),true);assertEquals("SCRAPE_SUCCEEDED",decode(response(t,"1",seconds(NOW)),t).get("observation_status"));}}
    @Test void missingDisabledAndUnsupportedNeverCallReader(){var service=new MonitoringScrapeObservationService(Map.of(),(s,t,e)->{throw new AssertionError();},Clock.fixed(NOW,ZoneOffset.UTC));assertEquals("CONFIG_PENDING",service.read(target("linux-node",true)).get("observation_status"));assertEquals("TARGET_DISABLED",service.read(target("linux-node",false)).get("observation_status"));assertEquals("UNSUPPORTED_ENGINE",service.read(target("zabbix-linux",true)).get("observation_status"));}
    @Test void sourceErrorsNeverReturnRawErrorsOrVerifiedHealth(){var t=target("linux-node",true);var s=new MonitoringScrapeObservationService(Map.of(TENANT,source("http://127.0.0.1:9090/api/v1/query")),(a,b,e)->{throw new IllegalStateException("secret credential");},Clock.fixed(NOW,ZoneOffset.UTC));var r=s.read(t);assertEquals("SOURCE_UNAVAILABLE",r.get("observation_status"));assertFalse(r.toString().contains("secret"));assertEquals(false,r.get("health_verified"));assertEquals(false,r.get("continuous_collection_verified"));assertNull(r.get("scrape_up"));}
    static ObjectNode sourceConfig(String endpoint){var root=MonitoringPresetRegistry.JSON.createObjectNode().put("version",1);root.putArray("sources").addObject().put("tenant_id",TENANT).put("endpoint",endpoint).put("max_age_seconds",60).put("lookback_seconds",300).put("timeout_seconds",1);return root;}
    @Test void sourcesRequireExactApprovalAndExplicitWindows(){String endpoint="http://127.0.0.1:9090/api/v1/query";var r=sourceConfig(endpoint);assertEquals(1,MonitoringScrapeObservationService.sources(r.toString(),"[\""+endpoint+"\"]").size());assertThrows(IllegalArgumentException.class,()->MonitoringScrapeObservationService.sources(r.toString(),"[]"));((ObjectNode)r.withArray("sources").get(0)).put("lookback_seconds",59);assertThrows(IllegalArgumentException.class,()->MonitoringScrapeObservationService.sources(r.toString(),"[\""+endpoint+"\"]"));}
    @Test void sourceUrlsAndCredentialFieldsAreStrict(){for(String endpoint:List.of("http://localhost:9090/api/v1/query","http://user:secret@127.0.0.1:9090/api/v1/query","http://169.254.169.254:9090/api/v1/query","http://127.0.0.1:9090/api/v1/query?query=up","http://127.0.0.1:9090/other","http://127.0.0.1/api/v1/query")){var r=sourceConfig(endpoint);assertThrows(IllegalArgumentException.class,()->MonitoringScrapeObservationService.sources(r.toString(),"[\""+endpoint+"\"]"));}var r=sourceConfig("http://127.0.0.1:9090/api/v1/query");((ObjectNode)r.withArray("sources").get(0)).put("password","secret");assertThrows(IllegalArgumentException.class,()->MonitoringScrapeObservationService.sources(r.toString(),"[]"));}
    @Test void registryOnlyModeNeverEnablesProbesAndLegacyFlagStillWorks(){var c=config("linux-node",true);var env=new MockEnvironment().withProperty("MOP_MONITORING_PRESET_REGISTRY_ENABLED","true").withProperty("MOP_MONITORING_PRESET_TARGETS",c.toString()).withProperty("MOP_MONITORING_PRESET_ALLOWED_ENDPOINTS","[\""+MonitoringPresetTest.row(c).get("endpoint").asText()+"\"]");var service=new MonitoringPresetConfiguration().monitoringPresetProbeService(env);var t=service.registry.forTenant(TENANT).get(0);assertTrue(service.enabled());assertFalse(service.testAuthorized(t));assertThrows(cn.mop.domain.DomainException.class,()->service.test(t));env.withProperty("MOP_MONITORING_PRESET_TEST_ENABLED","true").withProperty("MOP_MONITORING_PRESET_REGISTRY_ENABLED","false");assertThrows(IllegalArgumentException.class,()->new MonitoringPresetConfiguration().monitoringPresetProbeService(env));}
    @Test void readFlagDefaultsOffAndRejectsNonBoolean(){var c=new MonitoringPresetConfiguration();assertEquals("CONFIG_PENDING",c.monitoringScrapeObservationService(new MockEnvironment()).read(target("linux-node",true)).get("observation_status"));assertThrows(IllegalArgumentException.class,()->c.monitoringScrapeObservationService(new MockEnvironment().withProperty("MOP_MONITORING_PROMETHEUS_READ_ENABLED","yes")));}
    @Test void sourceSlotRejectsConcurrentReadAndReleasesAfterFailure()throws Exception{var started=new CountDownLatch(1);var release=new CountDownLatch(1);var s=new MonitoringScrapeObservationService(Map.of(TENANT,source("http://127.0.0.1:9090/api/v1/query")),(a,t,e)->{started.countDown();try{release.await();}catch(InterruptedException ex){Thread.currentThread().interrupt();}throw new IllegalStateException();},Clock.fixed(NOW,ZoneOffset.UTC));var pool=Executors.newSingleThreadExecutor();try{var f=pool.submit(()->s.read(target("linux-node",true)));assertTrue(started.await(2,TimeUnit.SECONDS));assertEquals(429,assertThrows(cn.mop.domain.DomainException.class,()->s.read(target("linux-node",true))).status);release.countDown();f.get();assertEquals("SOURCE_UNAVAILABLE",s.read(target("linux-node",true)).get("observation_status"));}finally{release.countDown();pool.shutdownNow();}}

    HttpServer server;AtomicInteger hits=new AtomicInteger(),httpStatus=new AtomicInteger(200),delay=new AtomicInteger();AtomicReference<String> body=new AtomicReference<>(),type=new AtomicReference<>("application/json"),seen=new AtomicReference<>();
    MonitoringScrapeObservationService http()throws Exception{var t=target("linux-node",true);body.set(response(t,"1",seconds(NOW.minusSeconds(5))).toString());server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",exchange->{hits.incrementAndGet();seen.set(exchange.getRequestURI().toString());try{if(delay.get()>0)Thread.sleep(delay.get());exchange.getResponseHeaders().set("Content-Type",type.get());exchange.getResponseHeaders().set("Location","http://192.0.2.99:1/no-follow");byte[] b=body.get().getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(httpStatus.get(),b.length);exchange.getResponseBody().write(b);}catch(Exception ignored){}finally{exchange.close();}});server.start();var source=source("http://127.0.0.1:"+server.getAddress().getPort()+"/api/v1/query");return new MonitoringScrapeObservationService(Map.of(TENANT,source),MonitoringScrapeObservationService.network(),Clock.fixed(NOW,ZoneOffset.UTC));}
    @AfterEach void stop(){if(server!=null)server.stop(0);}
    @Test void actualHttpUsesFixedBoundedScopeQuery()throws Exception{var s=http();assertEquals("SCRAPE_SUCCEEDED",s.read(target("linux-node",true)).get("observation_status"));String path=URLDecoder.decode(seen.get(),StandardCharsets.UTF_8);assertTrue(path.contains("timestamp(up{"));assertTrue(path.contains("mop_tenant_id=\""+TENANT+"\""));assertTrue(path.contains("&limit=3"));assertTrue(path.contains("&lookback_delta=300s"));assertEquals(1,hits.get());}
    @Test void actualHttpRejectsRedirectAndWrongContentType()throws Exception{var s=http();httpStatus.set(302);assertEquals("SOURCE_HTTP_REJECTED",s.read(target("linux-node",true)).get("reason"));assertEquals(1,hits.get());httpStatus.set(200);type.set("text/html");assertEquals("CONTENT_TYPE_REJECTED",s.read(target("linux-node",true)).get("reason"));}
    @Test void actualHttpEnforcesTotalTimeout()throws Exception{var s=http();delay.set(1800);long start=System.nanoTime();assertEquals("SOURCE_READ_TIMEOUT",s.read(target("linux-node",true)).get("reason"));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1600);}
    @Test void actualHttpRejectsOversizeAndMalformedPayload()throws Exception{var s=http();body.set("x".repeat(2*1024*1024+1));assertEquals("RESPONSE_TOO_LARGE",s.read(target("linux-node",true)).get("reason"));body.set("not-json secret");var out=s.read(target("linux-node",true));assertEquals("SOURCE_INVALID_RESPONSE",out.get("observation_status"));assertFalse(out.toString().contains("secret"));}
}
